set local statement_timeout='30s';
do $champion_redistribute$
declare
  patches jsonb := $champion_patch$[{"before":{"phase":"attack","level":"group","component":"Боротьба за перший м’яч","title":"Навчити партнерів визначати, хто вступає в боротьбу за перший контакт після передачі вперед.","description":"(Гравець першого контакту повідомляє «Я»; інший не заважає йому. Змінювати джерело доставки за форматом гри.)","age_from":10,"age_to":10,"sort_order":104,"audience":"field","goalkeeper_stage":null,"context":"play"},"after":{"phase":"attack","level":"group","component":"Боротьба за перший м’яч","title":"Навчити партнерів визначати, хто вступає в боротьбу за перший контакт після передачі вперед.","description":"(Гравець першого контакту повідомляє «Я»; інший не заважає йому. Змінювати джерело доставки за форматом гри.)","age_from":14,"age_to":14,"sort_order":104,"audience":"field","goalkeeper_stage":null,"context":"play"}},{"before":{"phase":"attack","level":"group","component":"Передача м’яча","title":"Навчити узгоджувати простріл із виходом партнера перед воротами.","description":"(Адресат показує зону й починає ривок за готовності виконавця передати; уникати одночасного виходу в одне місце.)","age_from":11,"age_to":11,"sort_order":130,"audience":"field","goalkeeper_stage":null,"context":"play"},"after":{"phase":"attack","level":"group","component":"Передача м’яча","title":"Навчити узгоджувати простріл із виходом партнера перед воротами.","description":"(Адресат показує зону й починає ривок за готовності виконавця передати; уникати одночасного виходу в одне місце. Простріл виконувати низом на посильну дистанцію.)","age_from":11,"age_to":11,"sort_order":130,"audience":"field","goalkeeper_stage":null,"context":"play"}},{"before":{"phase":"attack","level":"group","component":"Боротьба за перший м’яч","title":"Навчити узгоджувати передачу в боротьбу з діями визначеного гравця першого контакту.","description":"(До передачі підтвердити адресата й очікуваний напрямок продовження; варіювати доставку від воротаря, польового партнера та стандартів.)","age_from":11,"age_to":11,"sort_order":131,"audience":"field","goalkeeper_stage":null,"context":"play"},"after":{"phase":"attack","level":"group","component":"Боротьба за перший м’яч","title":"Навчити узгоджувати передачу в боротьбу з діями визначеного гравця першого контакту.","description":"(До передачі підтвердити адресата й очікуваний напрямок продовження; варіювати доставку від воротаря, польового партнера та стандартів.)","age_from":14,"age_to":14,"sort_order":131,"audience":"field","goalkeeper_stage":null,"context":"play"}},{"before":{"phase":"attack","level":"group","component":"Боротьба за перший м’яч","title":"Навчити гравця першого контакту обирати особисте оволодіння або спрямування м’яча партнеру.","description":"(Ураховувати тиск суперника; партнер показує доступність і повідомляє, куди потрібен м’яч.)","age_from":11,"age_to":11,"sort_order":132,"audience":"field","goalkeeper_stage":null,"context":"play"},"after":{"phase":"attack","level":"group","component":"Боротьба за перший м’яч","title":"Навчити гравця першого контакту обирати особисте оволодіння або спрямування м’яча партнеру.","description":"(Ураховувати тиск суперника; партнер показує доступність і повідомляє, куди потрібен м’яч.)","age_from":14,"age_to":14,"sort_order":132,"audience":"field","goalkeeper_stage":null,"context":"play"}},{"before":{"phase":"attack","level":"group","component":"Передача м’яча","title":"Навчити узгоджувати подачу з виходом партнера в обрану зону.","description":"(До виконання показати напрямок; адресат підлаштовує ривок під момент подачі.)","age_from":12,"age_to":12,"sort_order":158,"audience":"field","goalkeeper_stage":null,"context":"play"},"after":{"phase":"attack","level":"group","component":"Передача м’яча","title":"Навчити узгоджувати подачу з виходом партнера в обрану зону.","description":"(До виконання показати напрямок; адресат підлаштовує ривок під момент подачі. Дистанція подачі відповідає можливостям виконавця; починати без активної протидії.)","a