nce":"field","goalkeeper_stage":null,"context":"play"},"after":{"phase":"attack","level":"group","component":"Боротьба за перший м’яч","title":"Навчити ситуативно визначати гравця першого контакту після непередбачуваного винесення партнером.","description":"(Найкраще розташований повідомляє «Я»; інші змінюють намір, щоб не заважати йому.)","age_from":15,"age_to":15,"sort_order":189,"audience":"field","goalkeeper_stage":null,"context":"play"}},{"before":{"phase":"attack","level":"team","component":"Кутовий удар","title":"Навчити узгоджувати подачу з кутового в зону переваги адресата над опікуном.","description":"(Домовитися про цільову зону й сигнал; адресат показує готовність до виходу.)","age_from":13,"age_to":13,"sort_order":198,"audience":"field","goalkeeper_stage":null,"context":"standard"},"after":{"phase":"attack","level":"team","component":"Кутовий удар","title":"Навчити узгоджувати подачу з кутового в зону переваги адресата над опікуном.","description":"(Домовитися про цільову зону й сигнал; адресат показує готовність до виходу.)","age_from":15,"age_to":15,"sort_order":198,"audience":"field","goalkeeper_stage":null,"context":"standard"}},{"before":{"phase":"attack","level":"team","component":"Штрафний удар","title":"Навчити команду обирати зону подачі зі штрафного за розташуванням адресатів і захисників.","description":"(Виконавець і адресати узгоджують напрямок та сигнал початку ривків.)","age_from":13,"age_to":13,"sort_order":199,"audience":"field","goalkeeper_stage":null,"context":"standard"},"after":{"phase":"attack","level":"team","component":"Штрафний удар","title":"Навчити команду обирати зону подачі зі штрафного за розташуванням адресатів і захисників.","description":"(Виконавець і адресати узгоджують напрямок та сигнал початку ривків. Дистанція подачі відповідає можливостям виконавця.)","age_from":15,"age_to":15,"sort_order":199,"audience":"field","goalkeeper_stage":null,"context":"standard"}},{"before":{"phase":"defence","level":"individual","component":"Боротьба за м’яч","title":"Навчити випереджати суперника в боротьбі за м’яч у повітрі.","description":"(Оцінювати висоту й швидкість; низькі, середні та верхові м’ячі й дозволені способи контакту добирати за підготовленістю.)","age_from":13,"age_to":13,"sort_order":202,"audience":"field","goalkeeper_stage":null,"context":"play"},"after":{"phase":"defence","level":"individual","component":"Боротьба за м’яч","title":"Навчити випереджати суперника в боротьбі за м’яч у повітрі.","description":"(Оцінювати висоту й швидкість; низькі, середні та верхові м’ячі й дозволені способи контакту добирати за підготовленістю. Уникати небезпечних зіткнень.)","age_from":15,"age_to":15,"sort_order":202,"audience":"field","goalkeeper_stage":null,"context":"play"}},{"before":{"phase":"defence","level":"group","component":"Розподіл опіки","title":"Навчити партнерів добирати опікуна супернику за його небезпечними якостями.","description":"(Ураховувати швидкість, дальній удар або перевагу в повітрі; підтвердити розподіл до розвитку ситуації.)","age_from":13,"age_to":13,"sort_order":204,"audience":"field","goalkeeper_stage":null,"context":"play"},"after":{"phase":"defence","level":"group","component":"Розподіл опіки","title":"Навчити партнерів добирати опікуна супернику за його небезпечними якостями.","description":"(Ураховувати швидкість і дальній удар; підтвердити розподіл до розвитку ситуації.)","age_from":13,"age_to":13,"sort_order":204,"audience":"field","goalkeeper_stage":null,"context":"play"}},{"before":{"phase":"attack","level":"group","component":"Передача м’яча","title":"Навчити обирати адресата в різних лініях завершення за розташуванням захисників.","description":"(Помічати партнера перед воротами, у глибині зони або перед нею; адресати показують різні продовження.)","age_from":14,"age_to":14,"sort_order":213,"audience":"field","goalkeeper_stage":null,"context":"play"},"after":{"phase":"attack","level":"group","component":"Передача м’яча","title":"Навчити обирати адресата в різних лініях завершення за розташуванням захисників.","description":"(Помічати партнера перед воротами, у глибині зони або перед нею; адресати показують різні продовження.)","age_from":13,"age_to":13,"sort_order":213,"audience":"field","goalkeeper_stage":null,"context":"play"}},{"before":{"phase":"attack","level":"group","component":"Позиційна підтримка атаки","title":"Навчити групу перебудовувати підтримку після перекривання попередніх передач.","description":"(Один змінює місце, інші відкривають нові кути; узгоджувати переміщення, щоб не закритися одночасно.)","age_from":14,"age_to":14,"sort_order":214,"audience":"field","goalkeeper_stage":null,"context":"play"},"after":{"phase":"attack","level":"group","component":"Позиційна підтримка атаки","title":"Навчити групу перебудовувати підтримку після перекривання попередніх передач.","description":"(Один змінює місце, інші відкривають нові кути; узгоджувати переміщення, щоб не закритися одночасно.)","age_from":13,"age_to":13,"sort_order":214,"audience":"field","goalkeeper_stage":null,"context":"play"}},{"before":{"phase":"attack","level":"team","component":"Удар від воріт","title":"Навчити команду обирати довгу доставку від воріт за закритого короткого розіграшу.","description":"(Підтвердити гравця першого контакту та розташування для підбирання; сигнал воротаря змінює початковий план.)","age_from":14,"age_to":14,"sort_order":220,"audience":"field","goalkeeper_stage":null,"context":"standard"},"after":{"phase":"attack","level":"team","component":"Удар від воріт","title":"Навчити команду обирати довгу доставку від воріт за закритого короткого розіграшу.","description":"(Підтвердити гравця першого контакту та розташування для підбирання; сигнал воротаря змінює початковий план. Дистанція доставки відповідає можливостям виконавця.)","age_from":14,"age_to":14,"sort_order":220,"audience":"field","goalkeeper_stage":null,"context":"standard"}},{"before":{"phase":"attack","level":"team","component":"Вільний удар","title":"Навчити обирати просування через передачу під час вільного удару далеко від воріт.","description":"(Адресат показує напрямок; партнери не готують завершення, якщо до нього ще немає доступної доставки.)","age_from":14,"age_to":14,"sort_order":222,"audience":"field","goalkeeper_stage":null,"context":"standard"},"after":{"phase":"attack","level":"team","component":"Вільний удар","title":"Навчити обирати просування через передачу під час вільного удару далеко від воріт.","description":"(Адресат показує напрямок; партнери не готують завершення, якщо до нього ще немає доступної доставки.)","age_from":13,"age_to":13,"sort_order":222,"audience":"field","goalkeeper_stage":null,"context":"standard"}},{"before":{"phase":"defence","level":"team","component":"Удар від воріт суперника","title":"Навчити команду розподіляти опіку близьких адресатів короткого розіграшу суперником удару від воріт.","description":"(Підтвердити, хто виходить до м’яча; решта повідомляють про своїх адресатів і можливу передачу за спину.)","age_from":14,"age_to":14,"sort_order":236,"audience":"field","goalkeeper_stage":null,"context":"standard"},"after":{"phase":"defence","level":"team","component":"Удар від воріт суперника","title":"Навчити команду розподіляти опіку близьких адресатів короткого розіграшу суперником удару від воріт.","description":"(Підтвердити, хто виходить до м’яча; решта повідомляють про своїх адресатів і можливу передачу за спину.)","age_from":13,"age_to":13,"sort_order":236,"audience":"field","goalkeeper_stage":null,"context":"standard"}},{"before":{"phase":"defence","level":"individual","component":"Вихід на м’яч або суперника","title":"Навчити воротаря обирати вихід на подачу або залишення для захисту воріт.","description":"(Оцінювати траєкторію, гравців на шляху та свою досяжність; повідомити про рішення. Відпрацьовувати також на кутових.)","age_from":9,"age_to":12,"sort_order":319,"audience":"goalkeeper","goalkeeper_stage":"B","context":"play"},"after":{"phase":"defence","level":"individual","component":"Вихід на м’яч або суперника","title":"Навчити воротаря обирати вихід на подачу або залишення для захисту воріт.","description":"(Оцінювати траєкторію, гравців на шляху та свою досяжність; повідомити про рішення. Відпрацьовувати також на кутових. Висоту й швидкість доставки добирати за підготовленістю воротаря; уникати небезпечних зіткнень.)","age_from":9,"age_to":12,"sort_order":319,"audience":"goalkeeper","goalkeeper_stage":"B","context":"play"}}]$champion_patch$::jsonb;
  patch jsonb;
  current_task public.methodology_tasks%rowtype;
  actual jsonb;
  found_count integer;
  before_ids text;
  before_archived text;
  before_events text;
  before_materials text;
  actual_counts jsonb;
begin
  if (select count(*) from public.methodology_tasks where is_active) <> 349 then
    raise exception 'Expected 349 active curriculum tasks; no changes applied';
  end if;
  select md5(string_agg(id::text,',' order by id)) into before_ids from public.methodology_tasks;
  select md5(coalesce(string_agg(to_jsonb(t)::text,',' order by id),'')) into before_archived from public.methodology_tasks t where not is_active;
  select md5(coalesce(string_agg(to_jsonb(e)::text,',' order by id),'')) into before_events from public.events e;
  select md5(coalesce(string_agg(to_jsonb(m)::text,',' order by id),'')) into before_materials from public.methodology_materials m;

  for patch in select value from jsonb_array_elements(patches) loop
    select count(*) into found_count from public.methodology_tasks
      where is_active and sort_order=(patch->'before'->>'sort_order')::integer
      and title=patch->'before'->>'title' and audience=patch->'before'->>'audience';
    if found_count <> 1 then
      raise exception 'Expected one task at stable catalog position %, got %; no changes applied',patch->'before'->>'sort_order',found_count;
    end if;
    select * into strict current_task from public.methodology_tasks
      where is_active and sort_order=(patch->'before'->>'sort_order')::integer
      and title=patch->'before'->>'title' and audience=patch->'before'->>'audience'
      for update;
    actual=jsonb_build_object('phase',current_task.phase,'level',current_task.level,
      'component',current_task.component,'title',current_task.title,'description',current_task.description,
      'age_from',current_task.age_from,'age_to',current_task.age_to,'sort_order',current_task.sort_order,
      'audience',current_task.audience,'goalkeeper_stage',nullif(current_task.goalkeeper_stage,''),'context',current_task.context);
    if actual = patch->'before' then
      update public.methodology_tasks set
        age_from=(patch->'after'->>'age_from')::smallint,
        age_to=(patch->'after'->>'age_to')::smallint,
        description=patch->'after'->>'description'
        where id=current_task.id;
    elsif actual <> patch->'after' then
      raise exception 'Task at catalog position % differs from the reviewed source; no changes applied',current_task.sort_order;
    end if;
  end loop;

  select jsonb_object_agg(age_from::text,total) into actual_counts from (
    select age_from,count(*) as total from public.methodology_tasks
    where is_active and audience='field' group by age_from
  ) c;
  if actual_counts <> '{"6":16,"7":20,"8":26,"9":30,"10":29,"11":30,"12":30,"13":26,"14":26,"15":29,"16":22}'::jsonb then
    raise exception 'Unexpected final age allocation; no changes applied';
  end if;
  if exists(select 1 from public.methodology_tasks where is_active and audience='field'
    and component='Боротьба за перший м’яч' and age_from<14) then
    raise exception 'First-ball tasks must start at U14; no changes applied';
  end if;
  if before_ids is distinct from (select md5(string_agg(id::text,',' order by id)) from public.methodology_tasks)
    or before_archived is distinct from (select md5(coalesce(string_agg(to_jsonb(t)::text,',' order by id),'')) from public.methodology_tasks t where not is_active)
    or before_events is distinct from (select md5(coalesce(string_agg(to_jsonb(e)::text,',' order by id),'')) from public.events e)
    or before_materials is distinct from (select md5(coalesce(string_agg(to_jsonb(m)::text,',' order by id),'')) from public.methodology_materials m) then
    raise exception 'History or task identities changed; no changes applied';
  end if;
end;
$champion_redistribute$;
commit;
select audience,age_from,age_to,goalkeeper_stage,count(*) as tasks
from public.methodology_tasks where is_active
group by audience,age_from,age_to,goalkeeper_stage order by audience,age_from;
